  def setup
    @r = Shiftboard::Roster.new
    @setup = @r.add_shift(name: "Setup", day: D, start: 8, hours: 3, slots: 2)        # 1: Mon 08-11
    @bar = @r.add_shift(name: "Bar", day: D, start: 18, hours: 4, slots: 1)           # 2: Mon 18-22
