    @clean = @r.add_shift(name: "Cleanup", day: D + 6, start: 20, hours: 2, slots: 3) # 4: Sun 20-22
    @next = @r.add_shift(name: "Next week", day: D + 7, start: 8, hours: 6, slots: 2) # 5: Mon 08-14, next week
  end

