      @id = id
      @name = name
      @day = day
      @start = start
      @hours = hours
      @slots = slots
      @volunteers = []
      @skill = nil
    end

    def end_hour
      start + hours
    end

    def volunteers
      @volunteers.dup
    end

    def open_slots
      slots - @volunteers.size
