module Shiftboard
  # One block of work on a day.
  class Shift
    attr_reader :id, :name, :day, :start, :hours, :slots
    attr_reader :skill

    def initialize(id:, name:, day:, start:, hours:, slots:)
      @id = id
      @name = name
      @day = day
      @start = start
      @hours = hours
      @slots = slots
      @volunteers = []
      @skill = nil
