  def limited
    r = Shiftboard::Roster.new(max_hours: 12)
    r.add_shift(name: "Mon", day: D, start: 8, hours: 8, slots: 2)
    r.add_shift(name: "Tue", day: D + 1, start: 8, hours: 12 - 8, slots: 2)
