    assert_raises(Shiftboard::HoursLimit) { r.sign_up("ana", 2) }
    assert_equal 9, r.hours_for("ana")
    r.sign_up("cy", 3)
    r.sign_up("dee", 1)
    r.sign_up("dee", 2)
    assert_raises(Shiftboard::HoursLimit) { r.sign_up("dee", 3) }
    assert_equal ["ana", "cy"], r.fetch(3).volunteers
