      start + hours
    end

    def volunteers
      @volunteers.dup
    end

    def open_slots
      slots - @volunteers.size
    end

    def full?
      open_slots <= 0
    end

    # Used by the roster; not meant to be called from outside.
    def confirmed
      @volunteers
    end

    # Used by the roster; not meant to be called from outside.
    def require_skill(skill)
      @skill = skill
    end

    def waiting
      @waiting
    end
  end
end

