    assert_equal ["bob"], @r.fetch(2).volunteers
    assert_raises(KeyError) { @r.cancel("cy", 2) }
    assert_equal :waitlisted, @r.sign_up("dee", 2)
    @r.sign_up("eve", 1)
    @r.sign_up("fay", 1)
    @r.sign_up("gus", 1)
    @r.cancel("eve", 1)
    assert_equal ["fay", "gus"], @r.fetch(1).volunteers
    assert_equal [], @r.waitlist(1)
