    @gate = @r.add_shift(name: "Gate", day: D + 1, start: 9, hours: 8, slots: 2)      # 3: Tue 09-17
    @clean = @r.add_shift(name: "Cleanup", day: D + 6, start: 20, hours: 2, slots: 3) # 4: Sun 20-22
