    assert_raises(Shiftboard::AlreadySignedUp) { @r.swap("ana", 1, "bob", 2) }
    assert_equal ["ana"], @r.fetch(1).volunteers
    assert_equal ["bob"], @r.fetch(2).volunteers
    assert_equal ["ana"], @r.waitlist(2)
  end
