    @next = @r.add_shift(name: "Next week", day: D + 7, start: 8, hours: 6, slots: 2) # 5: Mon 08-14, next week
  end

  def test_base_add_shift_rules
    r = Shiftboard::Roster.new
    s = r.add_shift(name: "  Cooking ", day: D, start: 0, hours: 12, slots: 1)
