module Shiftboard
  # One block of work on a day.
  class Shift
    attr_reader :id, :name, :day, :start, :hours, :slots
    attr_reader :skill

    def initialize(id:, name:, day:, start:, hours:, slots:)
      @id = id
      @name = name
      @day = day
      @start = start
      @hours = hours
      @slots = slots
      @volunteers = []
      @skill = nil
      @waiting = []
    end

    def end_hour
      start + hours
    end

    def volunteers
      @volunteers.dup
    end

    def open_slots
      slots - @volunteers.size
    end

    def full?
      open_slots <= 0
    end

    # Used by the roster; not meant to be called from outside.
    def confirmed
      @volunteers
    end

    # Used by the roster; not meant to be called from outside.
    def require_skill(skill)
      @skill = skill
    end

    def waiting
      @waiting
    end
  end
end

